		if !tsIsPrimitiveValue(a) || !tsIsPrimitiveValue(b) {
			return tsLooseEqual(loop, tsDefaultPrimitive(loop, a), tsDefaultPrimitive(loop, b))
		}
		comparison, valid := tsBigIntCompare(a, b)
		return valid && comparison == 0
