	if b.kind == tsBooleanKind {
		return tsLooseEqual(loop, a, tsNumberValue(b.number))
	}
	if (tsIsSigned(a) || tsIsUnsigned(a)) && b.kind == tsStringKind {
		comparison, valid := tsIntegerStringCompare(a, (*tsString)(b.ref))
		return valid && comparison == 0
	}
