	if tsIsNumeric(a) && b.kind == tsStringKind {
		return tsStrictEqual(a, tsNumberValue(tsNumber(b)))
	}
	if tsIsNumeric(b) && a.kind == tsStringKind {
		return tsLooseEqual(loop, b, a)
	}
	if tsIsPrimitiveValue(a) && !tsNullish(a) && !tsIsPrimitiveValue(b) {
		return tsLooseEqual(loop, a, tsDefaultPrimitive(loop, b))
	}
	if tsIsPrimitiveValue(b) && !tsNullish(b) && !tsIsPrimitiveValue(a) {
		return tsLooseEqual(loop, tsDefaultPrimitive(loop, a), b)
	}
	return false
