func tsFSDirent(loop *tsLoop, entry os.DirEntry, parent string, encoding string) tsValue {
	out := tsNewObject()
	out.set("name", tsFSDecode([]byte(entry.Name()), encoding))
	parentValue := tsFSDecode([]byte(parent), encoding)
	out.set("parentPath", parentValue)
	out.set("path", parentValue)
	mode := entry.Type()
	if mode == 0 {
		if info, err := entry.Info(); err == nil {
			mode = info.Mode()
		}
	}
	tsFSSetTypePredicates(loop, out, mode)
	return tsObjectValue(out)
}

func tsFSReadDirectory(loop *tsLoop, path string, options tsValue, asynchronous bool) (tsValue, error) {
	out := &tsArray{}
	encoding := tsFSEncoding(loop, options, "utf8")
	withTypes := tsFSBooleanOption(loop, options, "withFileTypes", false)
	recursive := tsFSBooleanOption(loop, options, "recursive", false)
	bufferEncoding := encoding == "buffer"
	resultEncoding := encoding
	if recursive && asynchronous {
		resultEncoding = "utf8"
	}
	var walk func(string, string, bool) error
	walk = func(directory, prefix string, isRoot bool) error {
		handle, err := os.Open(directory)
		if err != nil {
			if !isRoot && recursive && tsFSReaddirSkipsSubdir(err) {
				return nil
			}
			return err
		}
		entries, readErr := handle.ReadDir(-1)
		closeErr := handle.Close()
		if readErr != nil {
			if !isRoot && recursive && tsFSReaddirSkipsSubdir(readErr) {
				return nil
			}
			return readErr
		}
		if closeErr != nil {
			return closeErr
		}
		for _, entry := range entries {
			name := filepath.Join(prefix, entry.Name())
			if bufferEncoding {
				out.values = append(out.values, tsNodeBuffer([]byte(name)))
			} else if withTypes {
				out.values = append(out.values, tsFSDirent(loop, entry, directory, resultEncoding))
			} else {
				out.values = append(out.values, tsFSDecode([]byte(name), resultEncoding))
			}
			if !recursive {
				continue
			}
			kind := entry.Type()
			if kind == 0 {
				if info, infoErr := entry.Info(); infoErr == nil {
					kind = info.Mode()
				}
			}
			if !entry.IsDir() && kind&os.ModeSymlink == 0 {
				continue
			}
			if len(entry.Name())+1+len(name) > 4096 {
				continue
			}
			child := filepath.Join(directory, entry.Name())
			info, statErr := os.Stat(child)
			if statErr != nil {
				if tsFSReaddirSkipsSubdir(statErr) {
					continue
				}
				return statErr
			}
			if info.IsDir() {
				if err := walk(child, name, false); err != nil {
					return err
				}
			}
		}
		return nil
	}
	err := walk(path, "", true)
	return tsArrayValue(out), err
}

func tsFSReaddirSkipsSubdir(err error) bool {
	return errors.Is(err, os.ErrNotExist) || errors.Is(err, syscall.ENOTDIR) || errors.Is(err, syscall.EPERM)
}

type tsFSDirectory struct {
	sync.Mutex
	file              *os.File
	path, encoding    string
	closed, recursive bool
	pending           []string
}

func (directory *tsFSDirectory) readEntry(loop *tsLoop) tsResult {
	directory.Lock()
	defer directory.Unlock()
	if directory.closed {
		return tsResult{tsFSException("Error", "ERR_DIR_CLOSED", "Directory handle was closed"), true}
	}
	for {
		if directory.file == nil {
			return tsResult{tsNull, false}
		}
		entries, err := directory.file.ReadDir(1)
		if err != nil && !errors.Is(err, io.EOF) {
			return tsResult{tsFSError(err, "readdir", directory.path, ""), true}
		}
		if len(entries) > 0 {
			entry := entries[0]
			if directory.recursive && (entry.IsDir() || entry.Type()&os.ModeSymlink != 0) {
				child := filepath.Join(directory.path, entry.Name())
				if info, e := os.Stat(child); e == nil && info.IsDir() {
					directory.pending = append(directory.pending, child)
				}
			}
			return tsResult{tsFSDirent(loop, entry, directory.path, directory.encoding), false}
		}
		if !directory.recursive {
			return tsResult{tsNull, false}
		}
		_ = directory.file.Close()
		directory.file = nil
		if len(directory.pending) == 0 {
			return tsResult{tsNull, false}
		}
		directory.path = directory.pending[0]
		directory.pending = directory.pending[1:]
		directory.file, err = os.Open(directory.path)
		if err != nil {
			return tsResult{tsFSError(err, "opendir", directory.path, ""), true}
		}
	}

}

func (directory *tsFSDirectory) close() tsResult {
	directory.Lock()
	defer directory.Unlock()
	if directory.closed {
		return tsResult{tsFSException("Error", "ERR_DIR_CLOSED", "Directory handle was closed"), true}
	}
	directory.closed = true
	if directory.file == nil {
		return tsResult{tsU, false}
	}
	if err := directory.file.Close(); err != nil {
		return tsResult{tsFSError(err, "closedir", directory.path, ""), true}
	}
	return tsResult{tsU, false}
}

