	offset := 0
	if !tsIsUndefined(tsArg(args, 1)) {
		offset = tsNodeBufferValidatedIndex(loop, tsArg(args, 1), "offset")
	}
	if offset >= array.length {
		return tsNodeBuffer([]byte{})
	}
	end := array.length
	if !tsIsUndefined(tsArg(args, 2)) {
		length := tsNodeBufferValidatedIndex(loop, tsArg(args, 2), "length")
		if length > array.length-offset {
			length = array.length - offset
		}
		end = offset + length
	}
	data := tsFSBytes(value)
	first, last := offset*array.bytes, end*array.bytes
