		key := uintptr(value.ref)
		if seen[key] {
			continue
		}
		seen[key] = true
		dependency := tsNodeVMValidateModule(value)
		if dependency.status == "unlinked" {
			dependency.status = "linked"
			tsNodeVMEnsureNamespace(dependency)
		}
