		colon := strings.IndexByte(line, ':')
		if colon <= 0 {
			return nil, line
		}
		field := line[:colon]
		if lenientFlags&1 != 0 {
			field = strings.TrimRight(field, " \t")
		}
		if !tsNodeHTTPCommonHTTPToken(field) {
			return nil, line
		}
		if max > 0 && len(pairs)/2 >= max {
			break
		}
		value := strings.TrimRight(strings.TrimLeft(line[colon+1:], " \t"), " \t")
		if tsNodeHTTPCommonHeaderValueInvalid(value, lenientFlags&1024 != 0) {
			return nil, line
		}
		pairs = append(pairs, tsNodeHTTPCommonKey(field), tsNodeHTTPCommonKey(value))
