func tsInternalTraceCategoryEnabled(category string) bool {
	return tsInternalTraceEvents.categoryRefs[category] > 0
}
func tsInternalTraceSetTid(value int) { tsInternalTraceEvents.tid = value }
func tsInternalTraceCategoryGroupEnabled(category string) bool {
	if len(tsInternalTraceEvents.categoryRefs) == 0 {
		return false
	}
	if tsInternalTraceCategoryEnabled(category) {
		return true
	}
	if !strings.Contains(category, ",") {
		return false
	}
	for _, part := range strings.Split(category, ",") {
		if tsInternalTraceCategoryEnabled(part) {
			return true
		}
	}
	return false
}
func tsInternalTraceEnableImpl(loop *tsLoop, categories []tsValue) {
	for _, value := range categories {
		category := tsText(value)
		count := tsInternalTraceEvents.categoryRefs[category]
		if count == 0 {
			tsInternalTraceEvents.categoryOrder = append(tsInternalTraceEvents.categoryOrder, category)
			tsInternalTraceEvents.everEnabled[category] = true
			if buffer := tsInternalTraceEvents.categoryBuffers[category]; buffer.kind == tsTypedArrayKind {
				(*tsTypedArray)(buffer.ref).write(0, 1)
			}
		}
		tsInternalTraceEvents.categoryRefs[category] = count + 1
	}
	if len(categories) > 0 {
		tsInternalTraceActivate(loop)
		tsInternalTraceInstallInstrumentation(loop)
	}
}
func tsInternalTraceDisable(categories []tsValue) {
	for _, value := range categories {
		category := tsText(value)
		count := tsInternalTraceEvents.categoryRefs[category]
		if count == 0 {
			continue
		}
		if count == 1 {
			delete(tsInternalTraceEvents.categoryRefs, category)
			if buffer := tsInternalTraceEvents.categoryBuffers[category]; buffer.kind == tsTypedArrayKind {
				(*tsTypedArray)(buffer.ref).write(0, 0)
			}
			for i, name := range tsInternalTraceEvents.categoryOrder {
				if name == category {
					tsInternalTraceEvents.categoryOrder = append(tsInternalTraceEvents.categoryOrder[:i], tsInternalTraceEvents.categoryOrder[i+1:]...)
					break
				}
			}
		} else {
			tsInternalTraceEvents.categoryRefs[category] = count - 1
		}
	}
}
func tsInternalTraceEnablePublic(loop *tsLoop, categories []tsValue) {
	tsInternalTraceEvents.fileWriteRequested = true
	tsInternalTraceEnableImpl(loop, categories)
}
func tsInternalTraceEnabledString() tsValue {
	if len(tsInternalTraceEvents.categoryOrder) == 0 {
		return tsU
	}
	return tsStringReference(tsStringUTF8(strings.Join(tsInternalTraceEvents.categoryOrder, ",")))
}
