	for _, part := range strings.Split(query, "&") {
		if part == "" {
			continue
		}
		key, value, has := strings.Cut(part, "=")
		if !has {
			value = ""
		}
		k, err := url.QueryUnescape(key)
		if err != nil {
			k = key
		}
		v, err := url.QueryUnescape(value)
		if err != nil {
			v = value
		}
		pairs = append(pairs, [2]string{k, v})
	}
	return pairs
