func tsInternalReplCompileSource(loop *tsLoop, source, name string) tsValue {
	vm := tsNodeVMModule(loop)
	constructor := tsGet(loop, vm, tsStringReference(tsStringUTF8("Script")))
	options := tsNewObject()
	options.set("filename", tsStringReference(tsStringUTF8(name)))
	script := tsConstruct(loop, constructor, tsStringReference(tsStringUTF8(source)), tsObjectValue(options))
	run := tsGet(loop, script, tsStringReference(tsStringUTF8("runInThisContext")))
	return tsCallReceiver(loop, run, script)
}
func tsInternalReplEvaluateBundle(loop *tsLoop, source, name string) tsValue {
	wrapper := tsInternalReplCompileSource(loop, source, name)
	exports := tsNewObject()
	module := tsNewObject()
	module.set("exports", tsObjectValue(exports))
	tsCall(loop, wrapper, tsObjectValue(exports), tsObjectValue(module))
	result := tsGet(loop, tsObjectValue(module), tsStringReference(tsStringUTF8("exports")))
	if result.kind == tsObjectKind {
		object := (*tsObject)(result.ref)
		if _, exists := object.values["default"]; !exists {
			object.set("default", result)
		}
	}
	return result
}

