	if strings.Contains(lower, "truecolor") {
		return tsNumberValue(c16m)
	}
	if strings.HasPrefix(lower, "xterm-256") {
		return tsNumberValue(c256)
	}
	for _, name := range []string{"eterm", "cons25", "console", "cygwin", "dtterm", "gnome", "hurd", "jfbterm", "konsole", "kterm", "mlterm", "mosh", "putty", "st", "rxvt-unicode-24bit", "terminator", "xterm-kitty"} {
		if lower == name {
			if name == "mosh" || name == "rxvt-unicode-24bit" || name == "terminator" || name == "xterm-kitty" {
				return tsNumberValue(c16m)
			}
			return tsNumberValue(c16)
		}
	}
	for _, prefix := range []string{"rxvt", "screen", "xterm", "vt100", "vt220"} {
		if strings.HasPrefix(lower, prefix) {
			return tsNumberValue(c16)
		}
	}
	if strings.Contains(lower, "ansi") || strings.Contains(lower, "color") || strings.Contains(lower, "linux") || strings.Contains(lower, "direct") || strings.HasPrefix(lower, "con") && strings.Contains(lower, "x") {
		return tsNumberValue(c16)
	}
