func tsNodeUtilGetCallSites(loop *tsLoop, args []tsValue) tsValue {
	count := tsArg(args, 0)
	options := tsArg(args, 1)
	if options.kind == tsUndefinedKind {
		optionsArg := tsArg(args, 0)
		if optionsArg.kind == tsObjectKind || optionsArg.kind == tsInstanceKind {
			options = optionsArg
			count = tsNumberValue(10)
		}
	}
	if tsIsUndefined(count) {
		count = tsNumberValue(10)
	}
	if !tsIsUndefined(options) {
		if options.kind != tsObjectKind && options.kind != tsInstanceKind {
			tsInternalValidatorInvalidType("options", "an object", options)
		}
		sourceMap := tsNodeUtilProperty(loop, options, "sourceMap")
		if !tsIsUndefined(sourceMap) && sourceMap.kind != tsBooleanKind {
			tsInternalValidatorInvalidType("options.sourceMap", "a boolean", sourceMap)
		}
	}
	tsInternalValidatorNumber(loop, count, tsNodeUtilString("frameCount"), tsNumberValue(1), tsNumberValue(200), true)
	pcs := make([]uintptr, int(tsNumber(count))+8)
	n := runtime.Callers(2, pcs)
	frames := runtime.CallersFrames(pcs[:n])
	out := &tsArray{}
	for index := 0; index < int(tsNumber(count)); index++ {
		frame, more := frames.Next()
		if !more {
			break
		}
		record := tsNewObject()
		record.set("functionName", tsNodeUtilString(frame.Function))
		record.set("scriptId", tsNodeUtilString("0"))
		record.set("scriptName", tsNodeUtilString(filepath.Base(frame.File)))
		record.set("lineNumber", tsNumberValue(float64(frame.Line)))
		record.set("columnNumber", tsNumberValue(1))
		record.set("column", tsNumberValue(1))
		out.values = append(out.values, tsObjectValue(record))
	}
	return tsArrayValue(out)
}

func tsNodeUtilConvertSignal(loop *tsLoop, signal tsValue) tsValue {
	osModule := tsNodeOSModule(loop)
	constants := tsNodeUtilProperty(loop, osModule, "constants")
	signals := tsNodeUtilProperty(loop, constants, "signals")
	choices := tsArrayValue(tsObjectKeys(loop, signals))
	tsInternalValidatorOneOf(signal, tsNodeUtilString("signalCode"), choices)
	return tsNumberValue(128 + tsNumber(tsNodeUtilProperty(loop, signals, tsText(signal))))
}

func tsNodeUtilAborted(loop *tsLoop, signal, resource tsValue) tsValue {
	if signal.kind != tsObjectKind || (*tsObject)(signal.ref).abort == nil {
		tsInternalValidatorInvalidType("signal", "an AbortSignal", signal)
	}
	if tsIsPrimitiveValue(resource) || tsNullish(resource) {
		tsInternalValidatorInvalidType("resource", "an object", resource)
	}
	state := (*tsObject)(signal.ref).abort
	promise := loop.promise()
	state.Lock()
	if state.aborted {
		state.Unlock()
		return tsPromiseValue(loop.resolved(tsU, false))
	}
	state.followers = append(state.followers, func(tsValue) { promise.settle(tsResult{tsU, false}) })
	state.Unlock()
	return tsPromiseValue(promise)
}

func tsNodeUtilTextCodec(loop *tsLoop, encoder bool) tsValue {
	name := "TextDecoder"
	if encoder {
		name = "TextEncoder"
	}
	constructor := &tsFunction{constructible: true, name: name, length: 0, properties: tsNewObject()}
	constructor.construct = func(loop *tsLoop, args ...tsValue) tsValue {
		out := tsNewObject()
		if encoder {
			out.set("encoding", tsNodeUtilString("utf-8"))
			out.set("encode", tsNamedNativeMethod("encode", 1, func(loop *tsLoop, _ tsValue, values ...tsValue) tsValue {
				input := tsArg(values, 0)
				text := ""
				if !tsIsUndefined(input) {
					text = tsNodeUtilText(loop, input)
				}
				return tsTypedArrayValue(tsNativeArray([]byte(text), "Uint8Array", func(value float64) uint8 { return uint8(value) }))
			}))
			out.set("encodeInto", tsNamedNativeMethod("encodeInto", 2, func(loop *tsLoop, _ tsValue, values ...tsValue) tsValue {
				input, destination := tsArg(values, 0), tsArg(values, 1)
				text := ""
				if !tsIsUndefined(input) {
					text = tsNodeUtilText(loop, input)
				}
				if destination.kind != tsTypedArrayKind || (*tsTypedArray)(destination.ref).name != "Uint8Array" {
					tsInternalValidatorInvalidType("destination", "a Uint8Array", destination)
				}
				bytes := []byte(text)
				array := (*tsTypedArray)(destination.ref)
				written := len(bytes)
				if written > array.length {
					written = array.length
				}
				for i := 0; i < written; i++ {
					array.write(i, float64(bytes[i]))
				}
				out := tsNewObject()
				out.set("read", tsNumberValue(float64(written)))
				out.set("written", tsNumberValue(float64(written)))
				return tsObjectValue(out)
			}))
		} else {
			label := tsArg(args, 0)
			encoding := "utf-8"
			if !tsIsUndefined(label) {
				encoding = strings.ToLower(tsNodeUtilText(loop, label))
			}
			switch encoding {
			case "utf-8", "utf8", "unicode-1-1-utf-8":
				encoding = "utf-8"
			case "utf-16le", "utf-16", "ucs-2", "ucs2":
				encoding = "utf-16le"
			case "latin1", "iso-8859-1", "ascii", "us-ascii", "windows-1252":
				encoding = "windows-1252"
			default:
				panic(tsThrown{tsFSException("RangeError", "ERR_ENCODING_NOT_SUPPORTED", "The "+encoding+" encoding is not supported")})
			}
			fatal := tsTruthy(tsArg(args, 1))
			ignoreBOM := tsTruthy(tsArg(args, 2))
			out.set("encoding", tsNodeUtilString(encoding))
			out.set("fatal", tsBooleanValue(fatal))
			out.set("ignoreBOM", tsBooleanValue(ignoreBOM))
			out.set("decode", tsNamedNativeMethod("decode", 1, func(loop *tsLoop, _ tsValue, values ...tsValue) tsValue {
				input := tsArg(values, 0)
				data := []byte{}
				if tsIsUndefined(input) || input.kind == tsNullKind {
					return tsNodeUtilString("")
				}
				switch input.kind {
				case tsArrayBufferKind:
					data = (*tsArrayBuffer)(input.ref).data
				case tsTypedArrayKind:
					array := (*tsTypedArray)(input.ref)
					if array.buffer.detached {
						tsArrayTypeFailure("Cannot decode a detached ArrayBufferView")
					}
					data = array.buffer.data[array.offset : array.offset+array.length*array.bytes]
				case tsDataViewKind:
					view := (*tsDataView)(input.ref)
					if view.buffer.detached {
						tsArrayTypeFailure("Cannot decode a detached ArrayBufferView")
					}
					data = view.buffer.data[view.offset : view.offset+view.length]
				default:
					tsInternalValidatorInvalidType("input", "an ArrayBuffer or view", input)
				}
				text := ""
				if encoding == "utf-16le" {
					units := make([]uint16, 0, len(data)/2)
					for i := 0; i+1 < len(data); i += 2 {
						units = append(units, uint16(data[i])|uint16(data[i+1])<<8)
					}
					text = string(utf16.Decode(units))
				} else if encoding == "windows-1252" {
					runes := make([]rune, len(data))
					for i, b := range data {
						runes[i] = rune(b)
						if encoding == "windows-1252" && strings.Contains("\u0080\u0082\u0083\u0084\u0085\u0086\u0087\u0088\u0089\u008a\u008b\u008c\u008e\u0091\u0092\u0093\u0094\u0095\u0096\u0097\u0098\u0099\u009a\u009b\u009c\u009e\u009f", string(runes[i])) {
							runes[i] = []rune("€‚ƒ„…†‡ˆ‰Š‹ŒŽ‘’“”•–—˜™š›œžŸ")[strings.IndexRune("\u0080\u0082\u0083\u0084\u0085\u0086\u0087\u0088\u0089\u008a\u008b\u008c\u008e\u0091\u0092\u0093\u0094\u0095\u0096\u0097\u0098\u0099\u009a\u009b\u009c\u009e\u009f", runes[i])]
						}
					}
					text = string(runes)
				} else {
					if fatal && !utf8.Valid(data) {
						panic(tsThrown{tsFSException("TypeError", "ERR_ENCODING_INVALID_ENCODED_DATA", "The encoded data was not valid for encoding utf-8")})
					}
					text = string(data)
				}
				if !ignoreBOM && strings.HasPrefix(text, "\ufeff") {
					text = strings.TrimPrefix(text, "\ufeff")
				}
				return tsNodeUtilString(text)
			}))
		}
		return tsObjectValue(out)
	}
	constructor.properties.set("name", tsNodeUtilString(name))
	constructor.properties.set("length", tsNumberValue(0))
	return tsFunctionValue(constructor)
}

