func tsNodeHistogramValue(loop *tsLoop, histogram *tsNodeHistogram) tsValue {
	if histogram.lowest == 0 {
		histogram.lowest = 1
	}
	if histogram.highest == 0 {
		histogram.highest = 9007199254740991
	}
	if histogram.figures == 0 {
		histogram.figures = 3
	}
	if histogram.manualMin == 0 {
		histogram.manualMin = 1<<63 - 1
	}
	object := tsNewObject()
	object.nativeClass = tsNativeClass(loop, "RecordableHistogram")
	object.prototype = tsObjectValue(tsNodeHistogramPrototype(loop))
	value := tsObjectValue(object)
	tsNodeHistogramStates.Store(value.ref, histogram)
	return value
}

func tsNodePerfDelaySchedule(loop *tsLoop, histogram tsValue) {
	tsNodePerfDelay.Lock()
	if !tsNodePerfDelay.enabled || tsNodePerfDelay.loop != loop {
		tsNodePerfDelay.Unlock()
		return
	}
	resolution := tsNodePerfDelay.resolution
	tsNodePerfDelay.Unlock()
	period := time.Duration(resolution) * time.Millisecond
	if period <= 0 {
		period = time.Millisecond
	}
	expected := time.Now().Add(period)
	callback := tsFunctionValue(tsFunc(func(loop *tsLoop, _ ...tsValue) tsValue {
		delay := time.Since(expected).Nanoseconds()
		if delay > 0 {
			if state := tsNodeHistogramState(histogram); state != nil {
				tsNodeHistogramRecord(state, tsNumberValue(float64(delay)))
			}
		}
		tsNodePerfDelay.Lock()
		active := tsNodePerfDelay.enabled && tsNodePerfDelay.loop == loop
		if active {
			tsNodePerfDelay.task = nil
		}
		tsNodePerfDelay.Unlock()
		if active {
			tsNodePerfDelaySchedule(loop, histogram)
		}
		return tsU
	}))
	task := loop.setTimeout(callback, tsNumberValue(float64(resolution)))
	task.unref = true
	tsNodePerfDelay.Lock()
	if tsNodePerfDelay.enabled && tsNodePerfDelay.loop == loop {
		tsNodePerfDelay.task = task
		tsNodePerfDelay.Unlock()
	} else {
		tsNodePerfDelay.Unlock()
		loop.clearTimeout(tsValue{ref: unsafe.Pointer(task), kind: tsTaskKind})
	}
}

func tsNodePerfHistogram(loop *tsLoop, args []tsValue) tsValue {
	options := tsArg(args, 0)
	if !tsIsUndefined(options) {
		tsInternalValidatorObject(options, tsStringReference(tsStringUTF8("options")), tsU)
	}
	lowestValue, highestValue, figuresValue := tsFSProperty(loop, options, "lowest"), tsFSProperty(loop, options, "highest"), tsFSProperty(loop, options, "figures")
	lowest, highest, figures := float64(1), float64(9007199254740991), float64(3)
	if !tsIsUndefined(lowestValue) {
		if lowestValue.kind == tsBigIntKind {
			lowest, _ = new(big.Float).SetInt((*big.Int)(lowestValue.ref)).Float64()
		} else if tsIsNumeric(lowestValue) {
			lowest = tsNumber(lowestValue)
		} else {
			tsInternalValidatorInvalidType("options.lowest", "a number or a bigint", lowestValue)
		}
	}
	if !tsIsUndefined(highestValue) {
		if highestValue.kind == tsBigIntKind {
			highest, _ = new(big.Float).SetInt((*big.Int)(highestValue.ref)).Float64()
		} else if tsIsNumeric(highestValue) {
			highest = tsNumber(highestValue)
		} else {
			tsInternalValidatorInvalidType("options.highest", "a number or a bigint", highestValue)
		}
	}
	if !tsIsUndefined(figuresValue) {
		if !tsIsNumeric(figuresValue) {
			tsInternalValidatorInvalidType("options.figures", "a number", figuresValue)
		}
		figures = tsNumber(figuresValue)
		if figures < 1 || figures > 5 {
			tsInternalValidatorOutOfRange("options.figures", ">= 1 && <= 5", figuresValue)
		}
	}
	if math.IsNaN(lowest) {
		lowest = 1
	}
	if math.IsNaN(highest) {
		highest = float64(1<<63 - 1)
	}
	if math.IsNaN(figures) {
		figures = 3
	}
	if lowest < 1 {
		tsInternalValidatorOutOfRange("options.lowest", ">= 1 && <= 9007199254740991", tsNumberValue(lowest))
	}
	if highest < 2*lowest {
		tsInternalValidatorOutOfRange("options.highest", ">= "+tsNumberText(2*lowest)+" && <= 9007199254740991", tsNumberValue(highest))
	}
	return tsNodeHistogramValue(loop, &tsNodeHistogram{lowest: tsNodeHistogramSigned(tsNumberValue(lowest)), highest: tsNodeHistogramSigned(tsNumberValue(highest)), figures: int(math.Trunc(figures)), manualMin: 1<<63 - 1})
}

func tsNodePerfMonitorEventLoopDelay(loop *tsLoop, args []tsValue) tsValue {
	options := tsArg(args, 0)
	resolution := 10
	if !tsIsUndefined(options) {
		tsInternalValidatorObject(options, tsStringReference(tsStringUTF8("options")), tsU)
		value := tsFSProperty(loop, options, "resolution")
		if !tsIsUndefined(value) {
			tsInternalValidatorNumber(loop, value, tsStringReference(tsStringUTF8("options.resolution")), tsNumberValue(1), tsNumberValue(2147483647), true)
			resolution = int(tsNumber(value))
		}
	}
	tsNodePerfDelay.Lock()
	defer tsNodePerfDelay.Unlock()
	tsNodePerfDelay.resolution = resolution
	if tsIsUndefined(tsNodePerfDelay.histogram) {
		tsNodePerfDelay.state = &tsNodeHistogram{lowest: 1, highest: 3600000000000, figures: 3, manualMin: 1<<63 - 1}
		tsNodePerfDelay.histogram = tsNodeHistogramValue(loop, tsNodePerfDelay.state)
		object := (*tsObject)(tsNodePerfDelay.histogram.ref)
		object.set("enable", tsNamedNativeMethod("enable", 0, func(loop *tsLoop, receiver tsValue, _ ...tsValue) tsValue {
			tsNodePerfDelay.Lock()
			if tsNodePerfDelay.enabled {
				tsNodePerfDelay.Unlock()
				return tsBooleanValue(false)
			}
			tsNodePerfDelay.enabled = true
			tsNodePerfDelay.loop = loop
			histogram := tsNodePerfDelay.histogram
			state := tsNodeHistogramState(histogram)
			state.counts = nil
			state.previous = 0
			state.exceeds = 0
			state.total = 0
			state.manualMin = 1<<63 - 1
			state.manualMax = 0
			tsNodePerfDelay.Unlock()
			tsNodePerfDelaySchedule(loop, histogram)
			return tsBooleanValue(true)
		}))
		object.set("disable", tsNamedNativeMethod("disable", 0, func(loop *tsLoop, _ tsValue, _ ...tsValue) tsValue {
			tsNodePerfDelay.Lock()
			if !tsNodePerfDelay.enabled {
				tsNodePerfDelay.Unlock()
				return tsBooleanValue(false)
			}
			tsNodePerfDelay.enabled = false
			task := tsNodePerfDelay.task
			tsNodePerfDelay.task = nil
			owner := tsNodePerfDelay.loop
			tsNodePerfDelay.Unlock()
			if task != nil && owner != nil {
				owner.clearTimeout(tsValue{ref: unsafe.Pointer(task), kind: tsTaskKind})
			}
			return tsBooleanValue(true)
		}))
		dispose := tsWellKnownSymbol("dispose")
		if !tsIsUndefined(dispose) {
			object.set(tsPropertyKey(loop, dispose), object.get(loop, "disable"))
		}
	}
	return tsNodePerfDelay.histogram
}

func tsNodePerfConstructor(name string, construct func(*tsLoop, ...tsValue) tsValue) tsValue {
	function := tsFunc(func(_ *tsLoop, _ ...tsValue) tsValue {
		tsPropertyFailure(name + " must be constructed with new")
		return tsU
	})
	function.name = name
	function.constructible = true
	function.construct = construct
	return tsFunctionValue(function)
}

