func tsInternalFSCPCopySyncError(loop *tsLoop, context tsValue, code, prefix string) tsValue {
	syscallName := tsText(tsFSProperty(loop, context, "syscall"))
	ctxMessage := tsText(tsFSProperty(loop, context, "message"))
	message := prefix + ": " + syscallName + " returned " + code + " (" + ctxMessage + ")"
	path, dest := tsFSProperty(loop, context, "path"), tsFSProperty(loop, context, "dest")
	if !tsIsUndefined(path) {
		message += " " + tsText(path)
	}
	if !tsIsUndefined(dest) {
		message += " => " + tsText(dest)
	}
	out := tsFSException("SystemError", code, message)
	if out.kind == tsErrorKind {
		err := (*tsRuntimeError)(out.ref)
		for name, value := range map[string]tsValue{
			"path": path, "dest": dest, "syscall": tsStringReference(tsStringUTF8(syscallName)),
			"errno": tsFSProperty(loop, context, "errno"), "info": context,
		} {
			if !tsIsUndefined(value) {
				err.fields[name] = value
			}
		}
	}
	return out
}

