func tsNodeCryptoDiffieHellman(loop *tsLoop, args []tsValue) tsValue {
	options := tsArg(args, 0)
	if options.kind != tsObjectKind && options.kind != tsInstanceKind {
		tsInternalValidatorInvalidType("options", "an object", options)
	}
	privateValue := tsGet(loop, options, tsNodeCryptoKey("privateKey"))
	publicValue := tsGet(loop, options, tsNodeCryptoKey("publicKey"))
	privateKey := tsNodeCryptoKeyFor(privateValue)
	publicKey := tsNodeCryptoKeyFor(publicValue)
	if privateKey == nil || privateKey.kind != "private" || privateKey.dh == nil {
		tsNodeCryptoError("TypeError", "ERR_INVALID_ARG_TYPE", "privateKey must be a Diffie-Hellman private KeyObject")
	}
	if publicKey == nil || (publicKey.kind != "public" && publicKey.kind != "private") || publicKey.dh == nil {
		tsNodeCryptoError("TypeError", "ERR_INVALID_ARG_TYPE", "publicKey must be a Diffie-Hellman public KeyObject")
	}
	privateDH, publicDH := privateKey.dh, publicKey.dh
	if privateDH.prime.Cmp(publicDH.prime) != 0 || privateDH.generator.Cmp(publicDH.generator) != 0 || privateDH.private == nil || publicDH.public == nil {
		tsNodeCryptoError("Error", "ERR_CRYPTO_INVALID_KEYTYPE", "Diffie-Hellman keys do not share parameters")
	}
	if publicDH.public.Cmp(big.NewInt(2)) < 0 || publicDH.public.Cmp(new(big.Int).Sub(privateDH.prime, big.NewInt(2))) > 0 {
		tsNodeCryptoError("Error", "ERR_CRYPTO_INVALID_KEYTYPE", "Supplied key is invalid")
	}
	secret := new(big.Int).Exp(publicDH.public, privateDH.private, privateDH.prime)
	return tsNodeBuffer(tsNodeCryptoDHPaddedBytes(secret, privateDH.prime))
}
