	tsNodeDgramSet(loop, state.stateObject, "receiving", tsBooleanValue(state.receiving))
	tsNodeDgramSet(loop, state.stateObject, "bindState", tsNumberValue(float64(state.bindState)))
	tsNodeDgramSet(loop, state.stateObject, "connectState", tsNumberValue(float64(state.connectState)))
