			if unsupportedHooks {
				tsNodeAsyncHooksWarning(loop, "async_hooks.createHook is not implemented in Bun. Hooks can still be created but will never be called.", &tsNodeAsyncHooksSingleton.createHookNotImplementedWarned)
			}
