	if stat, ok := info.Sys().(*syscall.Stat_t); ok {
		binary.LittleEndian.PutUint64(b, uint64(stat.Dev))
		binary.LittleEndian.PutUint64(b[8:], uint64(stat.Ino))
	}
	if info.IsDir() {
		b[16] = 3
	} else {
		b[16] = 4
	}
	binary.LittleEndian.PutUint64(b[24:], 1)
	binary.LittleEndian.PutUint64(b[32:], uint64(info.Size()))
	binary.LittleEndian.PutUint64(b[40:], uint64(info.ModTime().UnixNano()))
	binary.LittleEndian.PutUint64(b[48:], uint64(info.ModTime().UnixNano()))
	binary.LittleEndian.PutUint64(b[56:], uint64(info.ModTime().UnixNano()))
