var tsNodeV8Magic = []byte{0xff, 'T', 'S', 'V', 2}
var tsNodeV8MagicLegacy = []byte{0xff, 'T', 'S', 'V', 1}

func tsNodeV8HeaderVersion(data []byte) (int, int) {
	if bytes.HasPrefix(data, tsNodeV8Magic) {
		return 2, len(tsNodeV8Magic)
	}
	if bytes.HasPrefix(data, tsNodeV8MagicLegacy) {
		return 1, len(tsNodeV8MagicLegacy)
	}
	return 0, 0
}
