const (
	tsHTTP2StreamIdle uint8 = iota + 1
	tsHTTP2StreamOpen
	tsHTTP2StreamReservedLocal
	tsHTTP2StreamReservedRemote
	tsHTTP2StreamHalfClosedLocal
	tsHTTP2StreamHalfClosedRemote
	tsHTTP2StreamClosed
)
const (
	tsHTTP2EventSendHeaders uint8 = iota + 1
	tsHTTP2EventRecvHeaders
	tsHTTP2EventSendHeadersEndStream
	tsHTTP2EventRecvHeadersEndStream
	tsHTTP2EventSendEndStream
	tsHTTP2EventRecvEndStream
	tsHTTP2EventSendPushPromise
	tsHTTP2EventRecvPushPromise
	tsHTTP2EventSendRst
	tsHTTP2EventRecvRst
)
const (
	tsHTTP2TransitionProtocolError = iota + 1
	tsHTTP2TransitionStreamClosed
)

func tsHTTP2Transition(state, event uint8) (uint8, int) {
	protocol := tsHTTP2TransitionProtocolError
	closed := tsHTTP2TransitionStreamClosed
	switch state {
	case tsHTTP2StreamIdle:
		switch event {
		case tsHTTP2EventSendHeaders, tsHTTP2EventRecvHeaders:
			return tsHTTP2StreamOpen, 0
		case tsHTTP2EventSendHeadersEndStream:
			return tsHTTP2StreamHalfClosedLocal, 0
		case tsHTTP2EventRecvHeadersEndStream:
			return tsHTTP2StreamHalfClosedRemote, 0
		case tsHTTP2EventSendPushPromise:
			return tsHTTP2StreamReservedLocal, 0
		case tsHTTP2EventRecvPushPromise:
			return tsHTTP2StreamReservedRemote, 0
		default:
			return state, protocol
		}
	case tsHTTP2StreamReservedLocal:
		switch event {
		case tsHTTP2EventSendHeaders:
			return tsHTTP2StreamHalfClosedRemote, 0
		case tsHTTP2EventSendHeadersEndStream, tsHTTP2EventSendRst, tsHTTP2EventRecvRst:
			return tsHTTP2StreamClosed, 0
		default:
			return state, protocol
		}
	case tsHTTP2StreamReservedRemote:
		switch event {
		case tsHTTP2EventRecvHeaders:
			return tsHTTP2StreamHalfClosedLocal, 0
		case tsHTTP2EventRecvHeadersEndStream, tsHTTP2EventSendRst, tsHTTP2EventRecvRst:
			return tsHTTP2StreamClosed, 0
		default:
			return state, protocol
		}
	case tsHTTP2StreamOpen:
		switch event {
		case tsHTTP2EventSendEndStream, tsHTTP2EventSendHeadersEndStream:
			return tsHTTP2StreamHalfClosedLocal, 0
		case tsHTTP2EventRecvEndStream, tsHTTP2EventRecvHeadersEndStream:
			return tsHTTP2StreamHalfClosedRemote, 0
		case tsHTTP2EventSendRst, tsHTTP2EventRecvRst:
			return tsHTTP2StreamClosed, 0
		case tsHTTP2EventSendHeaders, tsHTTP2EventRecvHeaders:
			return tsHTTP2StreamOpen, 0
		default:
			return state, protocol
		}
	case tsHTTP2StreamHalfClosedLocal:
		switch event {
		case tsHTTP2EventRecvEndStream, tsHTTP2EventRecvHeadersEndStream, tsHTTP2EventSendRst, tsHTTP2EventRecvRst:
			return tsHTTP2StreamClosed, 0
		case tsHTTP2EventRecvHeaders:
			return tsHTTP2StreamHalfClosedLocal, 0
		default:
			return state, protocol
		}
	case tsHTTP2StreamHalfClosedRemote:
		switch event {
		case tsHTTP2EventSendEndStream, tsHTTP2EventSendHeadersEndStream, tsHTTP2EventSendRst, tsHTTP2EventRecvRst:
			return tsHTTP2StreamClosed, 0
		case tsHTTP2EventSendHeaders:
			return tsHTTP2StreamHalfClosedRemote, 0
		case tsHTTP2EventRecvEndStream, tsHTTP2EventRecvHeaders, tsHTTP2EventRecvHeadersEndStream:
			return state, closed
		default:
			return state, protocol
		}
	case tsHTTP2StreamClosed:
		if event == tsHTTP2EventSendRst || event == tsHTTP2EventRecvRst {
			return state, 0
		}
		return state, closed
	default:
		return state, protocol
	}
}
func tsHTTP2CanReceiveData(state uint8) bool {
	return state == tsHTTP2StreamIdle || state == tsHTTP2StreamOpen || state == tsHTTP2StreamHalfClosedLocal
}
func tsHTTP2CanSendData(state uint8) bool {
	return state == tsHTTP2StreamIdle || state == tsHTTP2StreamOpen || state == tsHTTP2StreamHalfClosedRemote
}

type tsHTTP2SendWindow struct{ remaining int64 }
type tsHTTP2RecvWindow struct{ size, consumed int64 }

func tsHTTP2NewSendWindow(initial uint32) tsHTTP2SendWindow {
	return tsHTTP2SendWindow{remaining: int64(initial)}
}
func tsHTTP2NewRecvWindow(initial uint32) tsHTTP2RecvWindow {
	return tsHTTP2RecvWindow{size: int64(initial)}
}
func (window tsHTTP2SendWindow) available() int64 {
	if window.remaining > 0 {
		return window.remaining
	}
	return 0
}
func (window *tsHTTP2SendWindow) consume(n int64) { window.remaining -= n }
func (window *tsHTTP2SendWindow) increase(increment uint32) int {
	next := window.remaining + int64(increment)
	if next > 0x7fffffff {
		return tsHTTP2ErrorFlowControl
	}
	window.remaining = next
	return tsHTTP2ErrorNoError
}
func (window *tsHTTP2SendWindow) applyInitialDelta(delta int64) {
	window.remaining = min(window.remaining+delta, int64(0x7fffffff))
}
func (window *tsHTTP2RecvWindow) onData(n int64)    { window.consumed += n }
func (window tsHTTP2RecvWindow) isOverflowed() bool { return window.consumed > window.size }
func (window tsHTTP2RecvWindow) isOverflowedWith(limit int64) bool {
	return window.consumed > max(limit, window.size)
}
func (window tsHTTP2RecvWindow) needsUpdate() bool {
	return window.consumed > 0 && window.consumed >= window.size/2
}
func (window *tsHTTP2RecvWindow) takeUpdate() uint32 {
	if window.consumed <= 0 {
		return 0
	}
	increment := min(window.consumed, int64(0x7fffffff))
	window.consumed -= increment
	return uint32(increment)
}
func (window *tsHTTP2RecvWindow) grow(delta int64) { window.size += delta }

