func tsNodeHTTP2ValidateHeadersFor(loop *tsLoop, owner, headers tsValue) {
	strict := true
	if session := tsNodeHTTP2State(owner); session != nil {
		strict = session.strictSingleValueFields
	} else if stream := tsNodeHTTP2Stream(owner); stream != nil {
		if session := tsNodeHTTP2State(stream.session); session != nil {
			strict = session.strictSingleValueFields
		}
	} else if tsNodeHTTP2Object(owner) {
		stream := tsNodeHTTP2Get(loop, owner, "stream")
		if streamState := tsNodeHTTP2Stream(stream); streamState != nil {
			if session := tsNodeHTTP2State(streamState.session); session != nil {
				strict = session.strictSingleValueFields
			}
		}
	}
	tsNodeHTTP2ValidateHeadersStrict(loop, headers, strict)
}
func tsNodeHTTP2Values(value tsValue) []tsValue {
	if value.kind == tsArrayKind {
		return (*tsArray)(value.ref).values
	}
	return []tsValue{value}
}
func tsNodeHTTP2HeaderArray(loop *tsLoop, headers tsValue) tsValue {
	out := &tsArray{}
	if tsNodeHTTP2Object(headers) {
		object := (*tsObject)(headers.ref)
		for _, name := range object.order {
			for _, value := range tsNodeHTTP2Values(object.values[name]) {
				out.values = append(out.values, tsNodeHTTP2Key(name), value)
			}
		}
	}
	return tsArrayValue(out)
}
