func tsNodeHTTP2SessionMemoryBytes(state *tsNodeHTTP2SessionState) uint64 {
	if state == nil {
		return 0
	}
	used := uint64(len(state.incoming) + len(state.corkedWriteBuffer))
	for _, item := range state.outgoing {
		used += uint64(len(item))
	}
	for _, item := range state.pendingTransportWrites {
		used += uint64(len(item))
	}
	for _, stream := range state.streams {
		used += 256
		if streamState := tsNodeHTTP2Stream(stream); streamState != nil {
			for _, write := range streamState.outbound {
				used += uint64(len(write.data))
			}
		}
	}
	return used
}
