func tsHTTP2IsArrayIndexName(name string) bool {
	if name == "" || len(name) > 10 {
		return false
	}
	if len(name) > 1 && name[0] == '0' {
		return false
	}
	value, err := strconv.ParseUint(name, 10, 32)
	return err == nil && value < math.MaxUint32
}
func tsHTTP2StatusNumber(value string) int32 {
	number, err := strconv.ParseFloat(strings.TrimSpace(value), 64)
	if err != nil || math.IsNaN(number) || math.IsInf(number, 0) || number == 0 {
		return 0
	}
	number = math.Mod(math.Trunc(number), 4294967296)
	if number < 0 {
		number += 4294967296
	}
	if number >= 2147483648 {
		number -= 4294967296
	}
	return int32(number)
}
func tsHTTP2IsSingleValueHeader(name string) bool { return tsHTTP2SingleValueHeaders[name] }
func tsNodeHTTP2MaterializeHeaders(loop *tsLoop, fields []tsHTTP2HeaderField) (tsValue, tsValue) {
	headers := tsNodeHTTP2EmptyObject()
	raw := &tsArray{}
	sensitive := &tsArray{}
	object := (*tsObject)(headers.ref)
	for _, field := range fields {
		name := tsHTTP2Latin1(field.name)
		value := tsHTTP2Latin1(field.value)
		nameValue := tsStringReference(tsStringUTF8(name))
		valueValue := tsStringReference(tsStringUTF8(value))
		raw.values = append(raw.values, nameValue, valueValue)
		if field.sensitive {
			sensitive.values = append(sensitive.values, nameValue)
		}
		fieldValue := valueValue
		if name == ":status" {
			fieldValue = tsNumberValue(float64(tsHTTP2StatusNumber(value)))
		}
		existing := object.get(loop, name)
		if tsIsUndefined(existing) {
			if name == "set-cookie" {
				object.set(name, tsArrayValue(&tsArray{values: []tsValue{fieldValue}}))
			} else {
				object.set(name, fieldValue)
			}
			continue
		}
		if tsHTTP2IsArrayIndexName(name) || tsHTTP2IsSingleValueHeader(name) {
			continue
		}
		if name == "set-cookie" {
			(*tsArray)(existing.ref).values = append((*tsArray)(existing.ref).values, fieldValue)
			continue
		}
		delimiter := ", "
		if name == "cookie" {
			delimiter = "; "
		}
		object.set(name, tsStringReference(tsStringUTF8(tsText(existing)+delimiter+value)))
	}
	symbol := tsValue{kind: tsSymbolKind, ref: unsafe.Pointer(tsNodeHTTP2Singleton.sensitiveHeaders)}
	tsSet(loop, headers, symbol, tsArrayValue(sensitive))
	return headers, tsArrayValue(raw)
}
