	status := tsNumber(tsNodeHTTP2Get(sink.loop, headers, ":status"))
	informational := status >= 100 && status < 200
	isTrailer := streamState != nil && streamState.headersReceived && !informational && !isPush
	if streamState != nil && !informational && !isPush {
		streamState.headersReceived = true
	}
