	fn.length = length
	fn.constructible = true
	fn.construct = func(loop *tsLoop, args ...tsValue) tsValue { return construct(loop, args) }
	fn.properties = tsNewObject()
	fn.properties.set("prototype", tsObjectValue(proto))
	fn.properties.descriptors = map[string]*tsDescriptor{"prototype": {writable: false}}
