	if err != nil {
		tsNodeSQLiteRethrowCallbackFailure(db)
		panic(tsThrown{tsNodeSQLiteError("ERR_SQLITE_ERROR", err.Error())})
	}
	tsNodeSQLiteRethrowCallbackFailure(db)
	state.executed = true
	if mode == "iterate" {
		releaseStepping = false
		return tsNodeSQLiteRowsIterator(loop, rows, state, columns)
	}
