func tsNodeTestRealTimeout(loop *tsLoop, milliseconds float64, finish func()) *tsTask {
	duration := time.Duration(milliseconds * float64(time.Millisecond))
	cancelled := make(chan struct{})
	task := loop.submit(func() tsResult {
		timer := time.NewTimer(duration)
		defer timer.Stop()
		select {
		case <-timer.C:
			return tsResult{tsU, false}
		case <-cancelled:
			return tsResult{tsU, false}
		}
	}, func(tsResult) { finish() })
	task.timer = true
	task.deadline = time.Now().Add(duration)
	task.cancel = func() { close(cancelled) }
	loop.timers = append(loop.timers, task)
	sort.SliceStable(loop.timers, func(i, j int) bool { return loop.timers[i].deadline.Before(loop.timers[j].deadline) })
	return task
}
