		if tsIsUndefined(value) {
			value = tsBooleanValue(true)
		}
		tsCall(loop, tsNodeTestGet(loop, tsInternalValidatorsModule(loop), "validateBoolean"), value, tsNodeTestKey("value"))
		node.onlyMode = tsTruthy(value)
		return tsU
