func tsNodeTestInvokeHook(loop *tsLoop, node *tsNodeTestNode, hook *tsNodeTestHookState) tsValue {
	promise := loop.promise()
	signal := hook.signal
	if !tsIsUndefined(signal) && tsTruthy(tsNodeTestGet(loop, signal, "aborted")) {
		promise.settle(tsResult{tsNodeTestGet(loop, signal, "reason"), true})
		return tsPromiseValue(promise)
	}
	timerEnabled := tsIsNumeric(hook.timeout) && !math.IsInf(tsNumber(hook.timeout), 0) && !math.IsNaN(tsNumber(hook.timeout))
	if !timerEnabled && tsIsUndefined(signal) {
		context := tsNodeTestContext(loop, node, node.suite)
		var result tsValue
		var failure any
		func() {
			defer func() { failure = recover() }()
			result = tsNodeTestInvokeCallback(loop, node, hook.fn, context)
		}()
		if failure != nil {
			return tsPromiseValue(loop.resolved(tsUnwrap(failure), true))
		}
		return result
	}
	settled := false
	var timer *tsTask
	var listener tsValue = tsU
	finish := func(result tsResult) {
		if settled {
			return
		}
		settled = true
		if timer != nil {
			loop.clearTimeout(tsTaskValue(timer))
			timer = nil
		}
		if !tsIsUndefined(listener) {
			remove := tsNodeTestGet(loop, signal, "removeEventListener")
			if remove.kind == tsFunctionKind {
				tsCallReceiver(loop, remove, signal, tsNodeTestKey("abort"), listener)
			}
		}
		promise.settle(result)
	}
	if !tsIsUndefined(signal) {
		listener = tsFunctionValue(tsFunc(func(loop *tsLoop, _ ...tsValue) tsValue {
			finish(tsResult{tsNodeTestGet(loop, signal, "reason"), true})
			return tsU
		}))
		options := tsNewObject()
		options.set("once", tsBooleanValue(true))
		add := tsNodeTestGet(loop, signal, "addEventListener")
		tsCallReceiver(loop, add, signal, tsNodeTestKey("abort"), listener, tsObjectValue(options))
	}
	if timerEnabled {
		timeout := tsNumber(hook.timeout)
		timer = tsNodeTestRealTimeout(loop, timeout, func() {
			timer = nil
			finish(tsResult{tsNodeTestError(fmt.Sprintf("test timed out after %gms", timeout)), true})
		})
	}
	context := tsNodeTestContext(loop, node, node.suite)
	var result tsValue
	var failure any
	func() {
		defer func() { failure = recover() }()
		result = tsNodeTestInvokeCallback(loop, node, hook.fn, context)
	}()
	if failure != nil {
		finish(tsResult{tsUnwrap(failure), true})
	} else {
		loop.await(result, finish)
	}
	return tsPromiseValue(promise)
}
