func tsNodeTestNotImplemented(feature string, issue int, extra string) {
	message := feature + " is not yet implemented in Bun."
	if issue != 0 {
		message += " Track the status & thumbs up the issue: https://github.com/oven-sh/bun/issues/" + strconv.Itoa(issue)
	}
	if extra != "" {
		message += ". " + extra
	}
	panic(tsThrown{tsErrorValue(&tsRuntimeError{name: "NotImplementedError", message: message, fields: map[string]tsValue{"code": tsNodeTestKey("ERR_NOT_IMPLEMENTED")}})})
}
func tsNodeTestRun(loop *tsLoop, args []tsValue) tsValue {
	options := tsArg(args, 0)
	if tsNullish(options) {
		options = tsObjectValue(tsNewObject())
	}
	options = tsNodeTestValidateRunOptions(loop, options)
	files := tsNodeTestGet(loop, options, "files")
	if tsTruthy(tsNodeTestGet(loop, options, "watch")) {
		tsNodeTestNotImplemented("run({ watch: true })", 5090, "Use bun:test --watch in the interim.")
	}
	if tsTruthy(tsNodeTestGet(loop, options, "coverage")) {
		tsNodeTestNotImplemented("run({ coverage: true })", 5090, "Use bun:test --coverage in the interim.")
	}
	if !tsNullish(tsNodeTestGet(loop, options, "shard")) {
		tsNodeTestNotImplemented("run({ shard })", 5090, "")
	}
	if tsText(tsNodeTestGet(loop, options, "isolation")) == "none" {
		tsNodeTestNotImplemented("run({ isolation: 'none' })", 5090, "")
	}
	if glob := tsNodeTestGet(loop, options, "globPatterns"); glob.kind == tsArrayKind && (*tsArray)(glob.ref).length() > 0 {
		tsNodeTestNotImplemented("run({ globPatterns })", 5090, "")
	}
	if !tsNullish(tsNodeTestGet(loop, options, "globalSetupPath")) {
		tsNodeTestNotImplemented("run({ globalSetupPath })", 5090, "")
	}
	if tsTruthy(tsNodeTestGet(loop, options, "only")) {
		tsNodeTestNotImplemented("run({ only: true })", 5090, "")
	}
	if !tsNullish(tsNodeTestGet(loop, options, "testNamePatterns")) {
		tsNodeTestNotImplemented("run({ testNamePatterns })", 5090, "")
	}
	if !tsNullish(tsNodeTestGet(loop, options, "testSkipPatterns")) {
		tsNodeTestNotImplemented("run({ testSkipPatterns })", 5090, "")
	}
	if tsTruthy(tsNodeTestGet(loop, options, "forceExit")) {
		tsNodeTestNotImplemented("run({ forceExit: true })", 5090, "")
	}
	if !tsNullish(tsNodeTestGet(loop, options, "concurrency")) {
		tsNodeTestNotImplemented("run({ concurrency })", 5090, "")
	}
	if tsNullish(files) {
		tsRuntimeUnsupported("node:test run() default file discovery", "the Go program cannot discover and execute dynamic source files")
	}
	tsRuntimeUnsupported("node:test run({ files })", "the Go program is statically compiled and cannot execute dynamic source files")
	return tsU
}
